record.field:
action = False


def toast(title, message, kind='warning', sticky=False):
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': title,
            'message': message,
            'type': kind,
            'sticky': sticky,
        }
    }


type_config = {
    'exclusive_employment_declaration': {
        'form_code': 'MCEP-HR-F-0010',
        'report_xmlid': 'hr_employment_custom.action_report_mcep_employee_f0010_exclusive_work',
        'filename_label': 'Exclusive Work Declaration',
    },
    'occupational_safety_acknowledgment': {
        'form_code': 'MCEP-HR-F-0013',
        'report_xmlid': 'hr_employment_custom.action_report_mcep_employee_f0013_occupational_safety',
        'filename_label': 'Occupational Safety Acknowledgment',
    },
    'human_waste_handling_employee_undertaking': {
        'form_code': 'MCEP-HR-F-0021',
        'report_xmlid': 'hr_employment_custom.action_report_mcep_employee_f0021_human_waste_handling',
        'filename_label': 'Human Waste Handling Undertaking',
    },
    'human_waste_storage_supervisor_undertaking': {
        'form_code': 'MCEP-HR-F-0022',
        'report_xmlid': 'hr_employment_custom.action_report_mcep_employee_f0022_human_waste_storage_supervisor',
        'filename_label': 'Human Waste Storage Supervisor Undertaking',
    },
}


for rec in records.sudo():
    config = type_config.get(rec.x_declaration_type or '')
    if not config:
        action = toast(
            'Generate PDF',
            'PDF generation is enabled only for the declaration templates already implemented in Pass 15.',
            'warning',
            False
        )
        continue

    if rec.x_state in ('signature_requested', 'signed'):
        action = toast(
            'Generate PDF',
            'This declaration has already entered the signature lifecycle. PDF regeneration is blocked.',
            'warning',
            True
        )
        continue

    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    if not employee:
        action = toast(
            'Generate PDF',
            'Cannot generate the declaration PDF without a linked employee.',
            'danger',
            True
        )
        continue

    generated_on = datetime.datetime.now()
    form_code = rec.x_form_code or config['form_code']

    vals = {}
    if not rec.x_state:
        vals['x_state'] = 'draft'
    if not rec.x_form_code:
        vals['x_form_code'] = form_code
    if not rec.x_document_reference:
        vals['x_document_reference'] = '%s-EMP-%05d-%05d' % (form_code, employee.id, rec.id)
    if rec.x_declaration_type == 'exclusive_employment_declaration' and not rec.x_hr_responsible_job_title:
        vals['x_hr_responsible_job_title'] = 'مدير الموارد البشرية'

    if vals:
        rec.write(vals)
        rec = rec.sudo().browse(rec.id)

    report_service = env['ir.actions.report'].sudo()
    pdf_content, _content_type = report_service._render_qweb_pdf(
        config['report_xmlid'],
        [rec.id]
    )

    filename = '%s - %s.pdf' % (
        rec.x_document_reference or config['form_code'],
        config['filename_label']
    )

    attachment = env['ir.attachment'].sudo().create({
        'name': filename,
        'type': 'binary',
        'raw': pdf_content,
        'mimetype': 'application/pdf',
        'res_model': rec._name,
        'res_id': rec.id,
    })

    rec.write({
        'x_pdf_attachment_id': attachment.id,
        'x_generated_on': generated_on,
        'x_state': 'generated',
    })

    body = 'تم توليد الإقرار: %s' % (rec.x_name or rec.x_document_reference or filename)

    employee.message_post(
        body=body,
        subtype_xmlid='mail.mt_note',
        attachment_ids=[attachment.id],
    )

    action = {
        'type': 'ir.actions.act_url',
        'url': '/web/content/%s?download=true' % attachment.id,
        'target': 'self',
    }
